/// <summary>
/// Initializes the field mapping.
/// </summary>
protected void initializeFieldValueMap()
{
    next initializeFieldValueMap();

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        this.insertFieldValueMapPair(tableNum(PriceDiscTable), fieldNum(PriceDiscTable, PricingRuleHeader), this.formattedQueryValue(fieldStr(PriceDiscAdmTrans, PricingRuleHeader)));
        this.insertFieldValueMapPair(tableNum(PriceDiscTable), fieldNum(PriceDiscTable, PricingRuleLine), this.formattedQueryValue(fieldStr(PriceDiscAdmTrans, PricingRuleLine)));
        this.insertFieldValueMapPair(tableNum(PriceDiscTable), fieldNum(PriceDiscTable, PriceComponentCombination), this.formattedQueryValue(fieldStr(PriceDiscAdmTrans, PriceComponentCombination)));
        this.insertFieldValueMapPair(tableNum(PriceDiscTable), fieldNum(PriceDiscTable, PriceApplyAdjustment), this.formattedQueryValue(fieldStr(PriceDiscAdmTrans, PriceApplyAdjustment)));
        this.insertFieldValueMapPair(tableNum(PriceDiscTable), fieldNum(PriceDiscTable, UnitAppliesToAll), this.formattedQueryValue(fieldStr(PriceDiscAdmTrans, UnitAppliesToAll)));
    }
}
